{
  "title": "How a microwave heats food",
  "screens": [
    {
      "title": "Hot outside, cold inside?",
      "text": "You take out a bowl of leftovers. The edge is steaming, but the middle is still cool. Why didn’t it all warm up together?",
      "imagePrompt": "A bowl of leftovers with steam rising from the edge and a cool-looking center"
    },
    {
      "title": "Waves enter the food",
      "text": "A microwave oven sends invisible waves into your food. They carry energy, and some of that energy is absorbed rather than passing through.",
      "imagePrompt": "Waves traveling from inside a microwave oven into a bowl of food"
    },
    {
      "title": "That energy becomes heat",
      "text": "The waves’ changing electric field makes water molecules shift back and forth. Charged particles can move too. As that motion spreads through the food, it warms up. It isn’t only water that can absorb the waves.",
      "imagePrompt": "A close-up of molecules moving within food as waves pass through"
    },
    {
      "title": "Heating varies by spot",
      "text": "Waves don’t reach or warm every part equally, especially in thick food. That’s why one part can be hot while another stays cool. A turntable helps by moving the food through different spots.",
      "imagePrompt": "A thick bowl of food on a turntable, with warmer and cooler areas"
    },
    {
      "title": "Give warmth time to spread",
      "text": "When you heat a bowl of chili, stirring brings cooler parts toward warmer ones. After heating, let it stand briefly: heat keeps moving into cooler areas. Check the middle before you eat.",
      "imagePrompt": "Someone stirring a bowl of chili, then checking a spoonful from the middle"
    }
  ],
  "check": {
    "question": "One side of your reheated chili is hot, but the other is cool. What should you do?",
    "options": [
      {
        "text": "Stir it, heat it more, let it stand, then check again.",
        "isCorrect": true,
        "feedback": "Right. Stirring and standing help spread heat, while reheating warms the cool parts."
      },
      {
        "text": "Heat it more without stirring, then check only the hot side.",
        "isCorrect": false,
        "feedback": "The hot side can’t tell you whether the cooler part has warmed enough."
      },
      {
        "text": "Let it stand without more heating, then eat it when it steams.",
        "isCorrect": false,
        "feedback": "Standing helps heat spread, but it may not warm a cool part enough."
      }
    ]
  },
  "recap": [
    "Microwave ovens send energy-carrying waves into food.",
    "Food absorbs some of that energy and warms up.",
    "Heating can be uneven, so stir, stand, and check the middle."
  ],
  "goFurther": {
    "overviewCourse": "Everyday Physics",
    "relatedQuestions": [
      "Why does metal spark in a microwave?",
      "Why does a microwave turntable spin?",
      "Why should food stand after microwaving?"
    ]
  }
}

{
  "title": "O que é inflação",
  "screens": [
