{
  "title": "Why the sky looks blue",
  "screens": [
    {
      "title": "Same Sun, different sky",
      "text": "You look up at noon and see blue. Later, the sky near the setting Sun looks orange. The sunlight is coming from the same place, so what changed?",
      "imagePrompt": "The same view at midday with a blue sky and at sunset with an orange sky"
    },
    {
      "title": "Sunlight carries many colors",
      "text": "Sunlight looks white, but it contains many colors mixed together. You can see them spread out in a rainbow.",
      "imagePrompt": "White sunlight passing through a raindrop and spreading into rainbow colors"
    },
    {
      "title": "Air spreads blue light",
      "text": "As sunlight travels through the air, tiny air molecules scatter some of it in new directions. They scatter blue light much more strongly than red light.",
      "imagePrompt": "Sunlight entering the atmosphere, with blue light spreading in many directions"
    },
    {
      "title": "Blue reaches your eyes",
      "text": "When you look away from the Sun, scattered blue light reaches you from all across the sky. That is why the daytime sky usually looks blue.",
      "imagePrompt": "A person looking at a blue patch of sky away from the Sun, with blue light arriving from that direction"
    },
    {
      "title": "Sunset takes a longer route",
      "text": "Near sunset, sunlight travels through more air before reaching you. Much of its blue light scatters away from the direct path, leaving the Sun and nearby sky looking more orange or red.",
      "imagePrompt": "Low Sun sending light through a long stretch of atmosphere toward a person, with blue light scattering away"
    }
  ],
  "check": {
    "question": "An astronaut stands on the Moon in bright sunlight. Why does the sky still look black?",
    "options": [
      {
        "text": "The Moon has almost no air to scatter sunlight across the sky.",
        "isCorrect": true,
        "feedback": "Right. Without much air to spread sunlight toward your eyes, the sky stays dark."
      },
      {
        "text": "Sunlight at the Moon contains almost no blue light.",
        "isCorrect": false,
        "feedback": "Sunlight still contains blue light. What is missing is enough air to scatter it."
      },
      {
        "text": "The Moon's ground absorbs blue light before it reaches the sky.",
        "isCorrect": false,
        "feedback": "The ground is not what makes Earth's sky blue. Air scatters sunlight across it."
      }
    ]
  },
  "recap": [
    "Sunlight contains many colors.",
    "Air scatters blue light more strongly than red light.",
    "Scattered blue reaches you across the sky; sunsets have a longer path through air."
  ],
  "goFurther": {
    "overviewCourse": "Everyday Physics",
    "relatedQuestions": [
      "Why are sunsets red?",
      "Why are clouds white?",
      "Why does the sky sometimes look gray?"
    ]
  }
}

